WITH BASE_TIME_INFO AS( SELECT CASE WHEN B."HOUR" IS NULL THEN A.SHIFT_DATE ELSE TO_CHAR(TO_DATE(A.SHIFT_DATE,'YYYYMMDD')+HOUR_FLAG,'YYYYMMDD') ||' '|| B."HOUR" END SHIFT_DATE , CASE WHEN B."HOUR" IS NULL THEN TO_DATE(A.SHIFT_DATE,'YYYYMMDD')+1+7.5/24 ELSE TO_DATE(TO_CHAR(TO_DATE(A.SHIFT_DATE,'YYYYMMDD')+HOUR_FLAG,'YYYYMMDD') ||' '|| B."HOUR",'YYYYMMDD HH24:MI') END SHIFT_DATE_LINE FROM( SELECT DISTINCT SHIFT_DATE FROM ODS.WP_CALENDAR WHERE SHIFT_DATE BETWEEN '20260803' AND '20260806' )A LEFT JOIN( SELECT CASE WHEN TO_CHAR(SYSDATE-7.5/24,'YYYYMMDD') BETWEEN '20260803' AND '20260806' THEN TO_CHAR(SYSDATE-7.5/24,'YYYYMMDD') WHEN TO_CHAR(SYSDATE-7.5/24,'YYYYMMDD')< '20260803' THEN '20260803' WHEN TO_CHAR(SYSDATE-7.5/24,'YYYYMMDD')> '20260806' THEN '20260806' END SHIFT_DATE ,HOUR,HOUR_FLAG FROM( SELECT '07:30' HOUR ,0 HOUR_FLAG FROM DUAL UNION ALL SELECT '09:30' HOUR ,0 HOUR_FLAG FROM DUAL UNION ALL SELECT '11:30' HOUR ,0 HOUR_FLAG FROM DUAL UNION ALL SELECT '13:30' HOUR ,0 HOUR_FLAG FROM DUAL UNION ALL SELECT '15:30' HOUR ,0 HOUR_FLAG FROM DUAL UNION ALL SELECT '17:30' HOUR ,0 HOUR_FLAG FROM DUAL UNION ALL SELECT '19:30' HOUR ,0 HOUR_FLAG FROM DUAL UNION ALL SELECT '21:30' HOUR ,0 HOUR_FLAG FROM DUAL UNION ALL SELECT '23:30' HOUR ,0 HOUR_FLAG FROM DUAL UNION ALL SELECT '01:30' HOUR ,1 HOUR_FLAG FROM DUAL UNION ALL SELECT '03:30' HOUR ,1 HOUR_FLAG FROM DUAL UNION ALL SELECT '05:30' HOUR ,1 HOUR_FLAG FROM DUAL ) )B ON A.SHIFT_DATE = B.SHIFT_DATE ) SELECT SUBSTR(SHIFT_DATE,5)SHIFT_DATE,REMAIN_EQP_COUNT,ACT_RECOVER_COUNT,FCST_RECOVER_COUNT ,CASE WHEN SYSDATE >= TO_DATE(SHIFT_DATE,'YYYYMMDD HH24:MI') THEN ROUND(ACT_RECOVER_COUNT*100/TOTAL_COUNT ,1) END ACT_RECOVER_RATIO ,ROUND(FCST_RECOVER_COUNT*100/TOTAL_COUNT,1) FCST_RECOVER_RATIO FROM( SELECT SHIFT_DATE,SUM(REMAIN_EQP_FLAG)REMAIN_EQP_COUNT ,SUM(ACT_RECOVER_FLAG)ACT_RECOVER_COUNT ,SUM(FCST_RECOVER_FLAG)FCST_RECOVER_COUNT , COUNT(1)TOTAL_COUNT ,MAX(SHIFT_DATE_LINE) SHIFT_DATE_LINE FROM( SELECT A.SHIFT_DATE,A.SHIFT_DATE_LINE ,B.EQP_ID,B.ACT_RETURN_TIME ,B.FCST_RETURN_TIME ,CASE WHEN B.ACT_RETURN_TIME IS NULL THEN 0 WHEN TRUNC(B.ACT_RETURN_TIME,'MI') <= SHIFT_DATE_LINE THEN 1 ELSE 0 END ACT_RECOVER_FLAG ,CASE WHEN TRUNC(B.FCST_RETURN_TIME,'MI') <=SHIFT_DATE_LINE THEN 1 ELSE 0 END FCST_RECOVER_FLAG ,CASE WHEN B.ACT_RETURN_TIME IS NULL AND FCST_RETURN_TIME < TRUNC(SYSDATE,'MI') AND SHIFT_DATE_LINE <= TRUNC(SYSDATE,'MI') THEN 1 WHEN B.ACT_RETURN_TIME IS NULL AND FCST_RETURN_TIME >= TRUNC(SYSDATE,'MI') AND SHIFT_DATE_LINE <= B.FCST_RETURN_TIME THEN 1 WHEN TRUNC(B.ACT_RETURN_TIME,'MI') > SHIFT_DATE_LINE THEN 1 ELSE 0 END REMAIN_EQP_FLAG FROM BASE_TIME_INFO A LEFT JOIN ( SELECT EQP_ID,ACT_RETURN_TIME,NVL(FCST_RETURN_TIME,TO_DATE('2026-08-07','YYYY-MM-DD'))FCST_RETURN_TIME FROM A1MFG.EQP_RECOVER_MONITOR_UPLOAD WHERE 1=1
AND MFG_MODULE = #{module}
) B ON 1=1 )GROUP BY SHIFT_DATE ) ORDER BY SHIFT_DATE_LINE

SELECT MODULE,MFG_MODULE,EQP_ID,RULE,PIRUN_FLAG ,RETURN_TIME,EE_WORK_TIME,PE_WORK_TIME,PAY_EQP_TIME,PE_MONITOR_TIME,FCST_RETURN_TIME ,UPDATE_USER,UPDATE_TIME,EQP_G,STATUS,STATUS_CODE,FAB_ID,ACT_RETURN_TIME,RETURN_FLAG,RETURN_DELAY_FLAG,DEAD_LINE ,F_COMMENT,PRIORITY FROM A1MFG.EQP_RECOVER_MONITOR_UPLOAD WHERE 1=1
AND MFG_MODULE = #{module}
ORDER BY PRIORITY

UPDATE A1MFG.EQP_RECOVER_MONITOR_UPLOAD SET UPDATE_TIME = SYSDATE ,UPDATE_USER = #{updateUser}
,ACT_RETURN_TIME = TO_DATE(#{actReturnTime},'YYYY-MM-DD HH24:MI:SS') ,RETURN_FLAG = 'Y' ,RETURN_DELAY_FLAG = CASE WHEN TO_DATE(#{actReturnTime},'YYYY-MM-DD HH24:MI:SS') >FCST_RETURN_TIME THEN 'N' ELSE 'Y' END
,ACT_RETURN_TIME = '' ,RETURN_FLAG = 'N' ,RETURN_DELAY_FLAG = CASE WHEN TRUNC(SYSDATE,'MI') >FCST_RETURN_TIME THEN 'N' ELSE 'Y' END
,F_COMMENT = #{fcomment}
WHERE EQP_ID = #{eqpId}

UPDATE PWEB.COMMENT_SUMMARY
SET KEY2 = #{key2},key3 = #{key3}
WHERE FUNCTION_NAME = '2026suixiuRecover'
AND KEY1 = #{key1}

SELECT SHIFT_DATE_LINE,HOUR ,MAX(PRI1_ACT)PRI1_ACT ,MAX(PRI1_TARGET)PRI1_TARGET ,MAX(PRI2_ACT)PRI2_ACT ,MAX(PRI2_TARGET)PRI2_TARGET ,MAX(PRI3_ACT)PRI3_ACT ,MAX(PRI3_TARGET)PRI3_TARGET ,MAX(PRI4_ACT)PRI4_ACT ,MAX(PRI4_TARGET)PRI4_TARGET FROM( SELECT SHIFT_DATE_LINE,"HOUR" ,CASE WHEN PRIORITY = 1 THEN ACT END PRI1_ACT ,CASE WHEN PRIORITY = 1 THEN TARGET END PRI1_TARGET ,CASE WHEN PRIORITY = 2 THEN ACT END PRI2_ACT ,CASE WHEN PRIORITY = 2 THEN TARGET END PRI2_TARGET ,CASE WHEN PRIORITY = 3 THEN ACT END PRI3_ACT ,CASE WHEN PRIORITY = 3 THEN TARGET END PRI3_TARGET ,CASE WHEN PRIORITY = 4 THEN ACT END PRI4_ACT ,CASE WHEN PRIORITY = 4 THEN TARGET END PRI4_TARGET FROM( SELECT SHIFT_DATE_LINE,HOUR,PRIORITY,FCST_RECOVER_COUNT - NVL(LAG(FCST_RECOVER_COUNT)OVER(PARTITION BY PRIORITY ORDER BY SHIFT_DATE_LINE),0)TARGET ,ACT_RECOVER_COUNT - NVL(LAG(ACT_RECOVER_COUNT)OVER(PARTITION BY PRIORITY ORDER BY SHIFT_DATE_LINE),0) ACT FROM( SELECT SHIFT_DATE_LINE,HOUR,PRIORITY ,SUM(FCST_RECOVER_FLAG)FCST_RECOVER_COUNT ,CASE WHEN SHIFT_DATE_LINE < SYSDATE THEN SUM(ACT_RECOVER_FLAG) END ACT_RECOVER_COUNT FROM( SELECT A.HOUR,A.SHIFT_DATE_LINE ,B.EQP_ID,B.ACT_RETURN_TIME ,B.FCST_RETURN_TIME ,B.PRIORITY ,CASE WHEN B.ACT_RETURN_TIME IS NULL THEN 0 WHEN TRUNC(B.ACT_RETURN_TIME,'MI')<= SHIFT_DATE_LINE THEN 1 ELSE 0 END ACT_RECOVER_FLAG ,CASE WHEN TRUNC(B.FCST_RETURN_TIME,'MI') <=SHIFT_DATE_LINE THEN 1 ELSE 0 END FCST_RECOVER_FLAG ,CASE WHEN B.ACT_RETURN_TIME IS NULL AND FCST_RETURN_TIME< TRUNC(SYSDATE,'MI') AND SHIFT_DATE_LINE<= TRUNC(SYSDATE,'MI') THEN 1 WHEN B.ACT_RETURN_TIME IS NULL AND FCST_RETURN_TIME >= TRUNC(SYSDATE,'MI') AND SHIFT_DATE_LINE <= B.FCST_RETURN_TIME THEN 1 WHEN TRUNC(B.ACT_RETURN_TIME,'MI') >SHIFT_DATE_LINE THEN 1 ELSE 0 END REMAIN_EQP_FLAG FROM( SELECT TO_DATE(SHIFT_DATE_LINE,'YYYYMMDD HH24:MI')SHIFT_DATE_LINE,HOUR FROM( SELECT CASE WHEN RN <=16 THEN TO_CHAR(SYSDATE-8.5/24,'YYYYMMDD') || ' ' || "HOUR" ELSE TO_CHAR(SYSDATE-8.5/24+1,'YYYYMMDD') || ' ' || "HOUR" END SHIFT_DATE_LINE ,HOUR FROM( SELECT CASE WHEN 7+ROWNUM>=24 THEN 7+ROWNUM-24||':30' ELSE 7+ROWNUM||':30' END HOUR ,ROWNUM RN FROM DUAL CONNECT BY ROWNUM <= 24 )) WHERE TO_CHAR(TO_DATE(SHIFT_DATE_LINE,'YYYYMMDD HH24:MI') -8.5/24,'YYYYMMDD') >= '20260415' )A JOIN ( SELECT EQP_ID,ACT_RETURN_TIME,FCST_RETURN_TIME,PRIORITY FROM A1MFG.EQP_RECOVER_MONITOR_UPLOAD WHERE 1=1
AND MFG_MODULE = #{module}
) B ON 1=1 )GROUP BY SHIFT_DATE_LINE,"HOUR",PRIORITY ) ))GROUP BY SHIFT_DATE_LINE,HOUR

WITH CUR_TIME_INFO AS( SELECT CASE WHEN TO_NUMBER(TO_CHAR(CUR_TIME,'MI'))>=30 THEN TRUNC(CUR_TIME,'HH24')+0.5/24 ELSE TRUNC(CUR_TIME,'HH24')- 0.5/24 END CUR_TIME FROM( SELECT DECODE(#{curDate,jdbcType=VARCHAR},NULL,SYSDATE,TO_DATE(#{curDate,jdbcType=VARCHAR},'YYYY-MM-DD HH24:MI')) CUR_TIME FROM DUAL ) ),ACT_INFO AS( SELECT NVL(MODULE,'MFG')MODULE,0 TOTAL_COUNT,SUM(ACT_RETURN_FLAG)DTH,SUM(DELAY_RECOVER_FLAG)DELAY_RECOVER_FLAG,'ACT' TYPE FROM( SELECT MODULE,EQP_G,EQP_ID,CUR_TIME,ACT_RETURN_TIME,ACT_RETURN_TIME2,FCST_RETURN_TIME ,CASE WHEN ACT_RETURN_TIME IS NOT NULL THEN 1 ELSE 0 END ACT_RETURN_FLAG ,CASE WHEN ACT_RETURN_TIME IS NULL AND FCST_RETURN_TIME< CUR_TIME THEN 1 ELSE 0 END DELAY_RECOVER_FLAG FROM( SELECT MODULE,EQP_G,EQP_ID,CUR_TIME ,CASE WHEN ACT_RETURN_TIME<= CUR_TIME THEN ACT_RETURN_TIME END ACT_RETURN_TIME ,ACT_RETURN_TIME ACT_RETURN_TIME2 ,FCST_RETURN_TIME FROM( SELECT A.MODULE,A.EQP_G,A.EQP_ID,B.CUR_TIME ,CASE WHEN TO_NUMBER(TO_CHAR(A.ACT_RETURN_TIME,'MI'))>30 THEN TRUNC(A.ACT_RETURN_TIME,'HH24')+1.5/24 ELSE TRUNC(A.ACT_RETURN_TIME,'HH24')+0.5/24 END ACT_RETURN_TIME ,CASE WHEN TO_NUMBER(TO_CHAR(A.FCST_RETURN_TIME,'MI'))>30 THEN TRUNC(A.FCST_RETURN_TIME,'HH24')+1.5/24 ELSE TRUNC(A.FCST_RETURN_TIME,'HH24')+0.5/24 END FCST_RETURN_TIME FROM A1MFG.EQP_RECOVER_MONITOR_UPLOAD A LEFT JOIN CUR_TIME_INFO B ON 1=1
WHERE A.PRIORITY = #{pri,jdbcType=VARCHAR}
)))GROUP BY ROLLUP(MODULE) ),PLAN_INFO AS( SELECT NVL(MODULE,'MFG')MODULE,COUNT(1) TOTAL_COUNT,SUM(FCST_RETURN_FLAG)DTH,'Plan' TYPE FROM( SELECT MODULE,EQP_G,EQP_ID,CUR_TIME,FCST_RETURN_TIME ,CASE WHEN FCST_RETURN_TIME< CUR_TIME THEN 1 ELSE 0 END FCST_RETURN_FLAG FROM( SELECT A.MODULE,A.EQP_G,A.EQP_ID,B.CUR_TIME ,CASE WHEN TO_NUMBER(TO_CHAR(A.FCST_RETURN_TIME,'MI'))>30 THEN TRUNC(A.FCST_RETURN_TIME,'HH24')+1.5/24 ELSE TRUNC(A.FCST_RETURN_TIME,'HH24')+0.5/24 END FCST_RETURN_TIME FROM A1MFG.EQP_RECOVER_MONITOR_UPLOAD A LEFT JOIN CUR_TIME_INFO B ON 1=1
WHERE A.PRIORITY = #{pri,jdbcType=VARCHAR}
))GROUP BY ROLLUP(MODULE) ) SELECT MODULE,'TTL' EQP_G,'TTL' EQP_ID,TOTAL_COUNT,DTH,DELAY_RECOVER_FLAG,"TYPE" ,RECOVER_COUNT,TOTAL_RECOVER_RATE,DTH_RECOVER_RATE ,CASE WHEN DTH_RECOVER_RATE< 95 THEN 'RED' WHEN DTH_RECOVER_RATE< 100 THEN 'YELLOW' ELSE 'GREEN' END STATUS FROM( SELECT MODULE,SUM(TOTAL_COUNT)OVER(PARTITION BY MODULE)TOTAL_COUNT,DTH ,SUM(DELAY_RECOVER_FLAG)OVER(PARTITION BY MODULE) DELAY_RECOVER_FLAG,TYPE ,SUM(RECOVER)OVER(PARTITION BY MODULE) RECOVER_COUNT ,ROUND(SUM(RECOVER)OVER(PARTITION BY MODULE)*100 / SUM(TOTAL_COUNT)OVER(PARTITION BY MODULE),1) TOTAL_RECOVER_RATE ,CASE WHEN SUM(CASE WHEN "TYPE" = 'Plan' THEN DTH END)OVER(PARTITION BY MODULE)>0 THEN ROUND(SUM(CASE WHEN "TYPE" = 'ACT' THEN DTH END)OVER(PARTITION BY MODULE) * 100 /SUM(CASE WHEN "TYPE" = 'Plan' THEN DTH END)OVER(PARTITION BY MODULE) ,1) END DTH_RECOVER_RATE FROM( SELECT MODULE,TOTAL_COUNT,DTH,DELAY_RECOVER_FLAG,"TYPE" ,DTH RECOVER FROM ACT_INFO A UNION ALL SELECT MODULE,TOTAL_COUNT,DTH,0 DELAY_RECOVER_FLAG ,"TYPE",0 RECOVER FROM PLAN_INFO A UNION ALL SELECT MODULE,TOTAL_COUNT,DTH,DELAY_RECOVER_FLAG,"TYPE" ,DTH RECOVER FROM ( SELECT A.MODULE, 0 TOTAL_COUNT, A.DTH-B.DTH DTH,0 DELAY_RECOVER_FLAG,'Gap'TYPE, 0 RECOVER FROM ACT_INFO A LEFT JOIN PLAN_INFO B ON A.MODULE = B.MODULE )))ORDER BY TOTAL_COUNT desc ,MODULE ,DECODE(TYPE,'Plan',1,'ACT',2,3),TYPE

WITH CUR_TIME_INFO AS( SELECT CASE WHEN TO_NUMBER(TO_CHAR(CUR_TIME,'MI'))>=30 THEN TRUNC(CUR_TIME,'HH24')+0.5/24 ELSE TRUNC(CUR_TIME,'HH24')- 0.5/24 END CUR_TIME FROM( SELECT DECODE(#{curDate,jdbcType=VARCHAR},NULL,SYSDATE,TO_DATE(#{curDate,jdbcType=VARCHAR},'YYYY-MM-DD HH24:MI')) CUR_TIME FROM DUAL ) ) ,ACT_INFO AS( SELECT MODULE,EQP_G,0 TOTAL_COUNT,SUM(ACT_RETURN_FLAG)DTH,SUM(DELAY_RECOVER_FLAG)DELAY_RECOVER_FLAG,'ACT' TYPE FROM( SELECT MODULE,EQP_G,EQP_ID,CUR_TIME,ACT_RETURN_TIME,ACT_RETURN_TIME2,FCST_RETURN_TIME ,CASE WHEN ACT_RETURN_TIME IS NOT NULL THEN 1 ELSE 0 END ACT_RETURN_FLAG ,CASE WHEN ACT_RETURN_TIME IS NULL AND FCST_RETURN_TIME < CUR_TIME THEN 1 ELSE 0 END DELAY_RECOVER_FLAG FROM( SELECT MODULE,EQP_G,EQP_ID,CUR_TIME ,CASE WHEN ACT_RETURN_TIME <= CUR_TIME THEN ACT_RETURN_TIME END ACT_RETURN_TIME ,ACT_RETURN_TIME ACT_RETURN_TIME2 ,FCST_RETURN_TIME FROM( SELECT A.MODULE,A.EQP_G,A.EQP_ID,B.CUR_TIME ,CASE WHEN TO_NUMBER(TO_CHAR(A.ACT_RETURN_TIME,'MI'))>30 THEN TRUNC(A.ACT_RETURN_TIME,'HH24')+1.5/24 ELSE TRUNC(A.ACT_RETURN_TIME,'HH24')+0.5/24 END ACT_RETURN_TIME ,CASE WHEN TO_NUMBER(TO_CHAR(A.FCST_RETURN_TIME,'MI'))>30 THEN TRUNC(A.FCST_RETURN_TIME,'HH24')+1.5/24 ELSE TRUNC(A.FCST_RETURN_TIME,'HH24')+0.5/24 END FCST_RETURN_TIME FROM A1MFG.EQP_RECOVER_MONITOR_UPLOAD A LEFT JOIN CUR_TIME_INFO B ON 1=1 WHERE MODULE = #{module,jdbcType=VARCHAR}
AND A.PRIORITY = #{pri,jdbcType=VARCHAR}
)))GROUP BY MODULE,EQP_G ),PLAN_INFO AS( SELECT MODULE,EQP_G,COUNT(1) TOTAL_COUNT,SUM(FCST_RETURN_FLAG)DTH,'Plan' TYPE FROM( SELECT MODULE,EQP_G,EQP_ID,CUR_TIME,FCST_RETURN_TIME ,CASE WHEN FCST_RETURN_TIME < CUR_TIME THEN 1 ELSE 0 END FCST_RETURN_FLAG FROM( SELECT A.MODULE,A.EQP_G,A.EQP_ID,B.CUR_TIME ,CASE WHEN TO_NUMBER(TO_CHAR(A.FCST_RETURN_TIME,'MI'))>30 THEN TRUNC(A.FCST_RETURN_TIME,'HH24')+1.5/24 ELSE TRUNC(A.FCST_RETURN_TIME,'HH24')+0.5/24 END FCST_RETURN_TIME FROM A1MFG.EQP_RECOVER_MONITOR_UPLOAD A LEFT JOIN CUR_TIME_INFO B ON 1=1 WHERE MODULE =#{module,jdbcType=VARCHAR}
AND A.PRIORITY = #{pri,jdbcType=VARCHAR}
))GROUP BY MODULE,EQP_G ) SELECT MODULE,EQP_G,'TTL' EQP_ID,TOTAL_COUNT,DTH,DELAY_RECOVER_FLAG,"TYPE",RECOVER_COUNT,TOTAL_RECOVER_RATE,DTH_RECOVER_RATE ,CASE WHEN DTH_RECOVER_RATE < 95 THEN 'RED' WHEN DTH_RECOVER_RATE < 100 THEN 'YELLOW' ELSE 'GREEN' END STATUS FROM( SELECT MODULE,EQP_G,SUM(TOTAL_COUNT)OVER(PARTITION BY EQP_G )TOTAL_COUNT,DTH,SUM(DELAY_RECOVER_FLAG)OVER(PARTITION BY EQP_G) DELAY_RECOVER_FLAG,TYPE ,SUM(RECOVER)OVER(PARTITION BY EQP_G) RECOVER_COUNT ,ROUND(SUM(RECOVER)OVER(PARTITION BY EQP_G)*100 / SUM(TOTAL_COUNT)OVER(PARTITION BY EQP_G),1) TOTAL_RECOVER_RATE ,CASE WHEN SUM(CASE WHEN "TYPE" = 'Plan' THEN DTH END)OVER(PARTITION BY EQP_G) >0 THEN ROUND(SUM(CASE WHEN "TYPE" = 'ACT' THEN DTH END)OVER(PARTITION BY EQP_G) * 100 /SUM(CASE WHEN "TYPE" = 'Plan' THEN DTH END)OVER(PARTITION BY EQP_G) ,1) END DTH_RECOVER_RATE FROM( SELECT MODULE,EQP_G,TOTAL_COUNT,DTH,DELAY_RECOVER_FLAG,"TYPE" ,DTH RECOVER FROM ACT_INFO A UNION ALL SELECT MODULE,EQP_G,TOTAL_COUNT,DTH,0 DELAY_RECOVER_FLAG ,"TYPE",0 RECOVER FROM PLAN_INFO A UNION ALL SELECT MODULE,EQP_G,TOTAL_COUNT,DTH,DELAY_RECOVER_FLAG,"TYPE" ,DTH RECOVER FROM ( SELECT A.MODULE,A.EQP_G, 0 TOTAL_COUNT, A.DTH-B.DTH DTH,0 DELAY_RECOVER_FLAG,'Gap'TYPE, 0 RECOVER FROM ACT_INFO A LEFT JOIN PLAN_INFO B ON A.MODULE = B.MODULE AND A.EQP_G = B.EQP_G ) ))ORDER BY TOTAL_COUNT desc ,MODULE,EQP_G ,DECODE(TYPE,'Plan',1,'ACT',2,3),TYPE

WITH CUR_TIME_INFO AS( SELECT CASE WHEN TO_NUMBER(TO_CHAR(CUR_TIME,'MI'))>=30 THEN TRUNC(CUR_TIME,'HH24')+0.5/24 ELSE TRUNC(CUR_TIME,'HH24')- 0.5/24 END CUR_TIME FROM( SELECT DECODE(#{curDate,jdbcType=VARCHAR},NULL,SYSDATE,TO_DATE(#{curDate,jdbcType=VARCHAR},'YYYY-MM-DD HH24:MI')) CUR_TIME FROM DUAL ) ) ,ACT_INFO AS( SELECT MODULE,EQP_G,EQP_ID,0 TOTAL_COUNT,SUM(ACT_RETURN_FLAG)DTH,SUM(DELAY_RECOVER_FLAG)DELAY_RECOVER_FLAG,'ACT' TYPE FROM( SELECT MODULE,EQP_G,EQP_ID,CUR_TIME,ACT_RETURN_TIME,ACT_RETURN_TIME2,FCST_RETURN_TIME ,CASE WHEN ACT_RETURN_TIME IS NOT NULL THEN 1 ELSE 0 END ACT_RETURN_FLAG ,CASE WHEN ACT_RETURN_TIME IS NULL AND FCST_RETURN_TIME< CUR_TIME THEN 1 ELSE 0 END DELAY_RECOVER_FLAG FROM( SELECT MODULE,EQP_G,EQP_ID,CUR_TIME ,CASE WHEN ACT_RETURN_TIME<= CUR_TIME THEN ACT_RETURN_TIME END ACT_RETURN_TIME ,ACT_RETURN_TIME ACT_RETURN_TIME2 ,FCST_RETURN_TIME FROM( SELECT A.MODULE,A.EQP_G,A.EQP_ID,B.CUR_TIME ,CASE WHEN TO_NUMBER(TO_CHAR(A.ACT_RETURN_TIME,'MI'))>30 THEN TRUNC(A.ACT_RETURN_TIME,'HH24')+1.5/24 ELSE TRUNC(A.ACT_RETURN_TIME,'HH24')+0.5/24 END ACT_RETURN_TIME ,CASE WHEN TO_NUMBER(TO_CHAR(A.FCST_RETURN_TIME,'MI'))>30 THEN TRUNC(A.FCST_RETURN_TIME,'HH24')+1.5/24 ELSE TRUNC(A.FCST_RETURN_TIME,'HH24')+0.5/24 END FCST_RETURN_TIME FROM A1MFG.EQP_RECOVER_MONITOR_UPLOAD A LEFT JOIN CUR_TIME_INFO B ON 1=1 WHERE EQP_G = #{eqpg,jdbcType=VARCHAR}
AND A.PRIORITY = #{pri,jdbcType=VARCHAR}
)))GROUP BY MODULE,EQP_G,EQP_ID ),PLAN_INFO AS( SELECT MODULE,EQP_G,EQP_ID,COUNT(1) TOTAL_COUNT,SUM(FCST_RETURN_FLAG)DTH,'Plan' TYPE FROM( SELECT MODULE,EQP_G,EQP_ID,CUR_TIME,FCST_RETURN_TIME ,CASE WHEN FCST_RETURN_TIME< CUR_TIME THEN 1 ELSE 0 END FCST_RETURN_FLAG FROM( SELECT A.MODULE,A.EQP_G,A.EQP_ID,B.CUR_TIME ,CASE WHEN TO_NUMBER(TO_CHAR(A.FCST_RETURN_TIME,'MI'))>30 THEN TRUNC(A.FCST_RETURN_TIME,'HH24')+1.5/24 ELSE TRUNC(A.FCST_RETURN_TIME,'HH24')+0.5/24 END FCST_RETURN_TIME FROM A1MFG.EQP_RECOVER_MONITOR_UPLOAD A LEFT JOIN CUR_TIME_INFO B ON 1=1 WHERE EQP_G = #{eqpg,jdbcType=VARCHAR}
AND A.PRIORITY = #{pri,jdbcType=VARCHAR}
))GROUP BY MODULE,EQP_G,EQP_ID ) SELECT MODULE,EQP_G,EQP_ID,TOTAL_COUNT,DTH,DELAY_RECOVER_FLAG,"TYPE",RECOVER_COUNT,TOTAL_RECOVER_RATE,DTH_RECOVER_RATE ,CASE WHEN DTH_RECOVER_RATE< 95 THEN 'RED' WHEN DTH_RECOVER_RATE< 100 THEN 'YELLOW' ELSE 'GREEN' END STATUS FROM( SELECT MODULE,EQP_G,EQP_ID,SUM(TOTAL_COUNT)OVER(PARTITION BY EQP_ID )TOTAL_COUNT,DTH,SUM(DELAY_RECOVER_FLAG)OVER(PARTITION BY EQP_ID) DELAY_RECOVER_FLAG,TYPE ,SUM(RECOVER)OVER(PARTITION BY EQP_ID) RECOVER_COUNT ,CASE WHEN SUM(TOTAL_COUNT)OVER(PARTITION BY EQP_ID)>0 THEN ROUND(SUM(RECOVER)OVER(PARTITION BY EQP_ID)*100 / SUM(TOTAL_COUNT)OVER(PARTITION BY EQP_ID),1) END TOTAL_RECOVER_RATE ,CASE WHEN SUM(CASE WHEN "TYPE" = 'Plan' THEN DTH END)OVER(PARTITION BY EQP_ID) >0 THEN ROUND(SUM(CASE WHEN "TYPE" = 'ACT' THEN DTH END)OVER(PARTITION BY EQP_ID) * 100 /SUM(CASE WHEN "TYPE" = 'Plan' THEN DTH END)OVER(PARTITION BY EQP_ID) ,1) END DTH_RECOVER_RATE FROM( SELECT MODULE,EQP_G,EQP_ID,TOTAL_COUNT,DTH,DELAY_RECOVER_FLAG,"TYPE" ,DTH RECOVER FROM ACT_INFO A UNION ALL SELECT MODULE,EQP_G,EQP_ID,TOTAL_COUNT,DTH,0 DELAY_RECOVER_FLAG ,"TYPE",0 RECOVER FROM PLAN_INFO A ))ORDER BY TOTAL_COUNT desc ,MODULE,EQP_G ,EQP_ID,DECODE(TYPE,'Plan',1,2),TYPE

WITH CUR_TIME_INFO AS( SELECT CASE WHEN TO_NUMBER(TO_CHAR(CUR_TIME,'MI'))>30 THEN TRUNC(CUR_TIME,'HH24')+0.5/24 ELSE TRUNC(CUR_TIME,'HH24')- 0.5/24 END CUR_TIME FROM( SELECT DECODE(#{curDate,jdbcType=VARCHAR},NULL,SYSDATE,TO_DATE(#{curDate,jdbcType=VARCHAR},'YYYY-MM-DD HH24:MI')) CUR_TIME FROM DUAL )), TIME_FLOW_INFO AS( SELECT * FROM( SELECT SHIFT_DATE_LINE,DATE_TIME,B.CUR_TIME FROM ( SELECT TO_CHAR(TO_DATE('2026-04-15 20:30','YYYY-MM-DD HH24:MI')+ROWNUM/24-1/24 ,'YYYY-MM-DD HH24:MI')SHIFT_DATE_LINE ,TO_DATE('2026-04-15 20:30','YYYY-MM-DD HH24:MI')+ROWNUM/24-1/24 DATE_TIME FROM DUAL CONNECT BY ROWNUM <= 109 )A LEFT JOIN CUR_TIME_INFO B ON A.DATE_TIME <= B.CUR_TIME )C LEFT JOIN ( SELECT DISTINCT MODULE FROM A1MFG.EQP_RECOVER_MONITOR_UPLOAD D UNION ALL SELECT 'MFG' FROM DUAL )D ON 1=1 ) ,PLAN_INFO AS( SELECT MODULE,EQP_G,EQP_ID,"TYPE",FCST_TIME,VALUE,SUM(VALUE)OVER(PARTITION BY MODULE,EQP_G,EQP_ID,"TYPE" ORDER BY FCST_TIME )VALUE_SUM FROM( SELECT NVL(MODULE,'MFG')MODULE,'TTL'EQP_G, 'TTL'EQP_ID,"TYPE",FCST_TIME,SUM(VALUE)VALUE FROM( SELECT EQP_G,MODULE,EQP_ID,'Plan' TYPE ,CASE WHEN FCST_RETURN_TIME <= TO_DATE('2026-04-15 20:30','YYYY-MM-DD HH24:MI') THEN TO_DATE('2026-04-15 20:30','YYYY-MM-DD HH24:MI') WHEN TO_NUMBER(TO_CHAR(FCST_RETURN_TIME,'MI'))>30 THEN TRUNC(FCST_RETURN_TIME,'HH24')+1.5/24 ELSE TRUNC(FCST_RETURN_TIME,'HH24')+0.5/24 END FCST_TIME ,1 VALUE FROM A1MFG.EQP_RECOVER_MONITOR_UPLOAD A
WHERE A.PRIORITY = #{pri,jdbcType=VARCHAR}
)GROUP BY ROLLUP(MODULE),"TYPE",FCST_TIME )) ,ACT_INFO AS( SELECT MODULE,EQP_G,EQP_ID,"TYPE",FCST_TIME,VALUE,SUM(VALUE)OVER(PARTITION BY MODULE,EQP_G,EQP_ID,"TYPE" ORDER BY FCST_TIME )VALUE_SUM FROM( SELECT NVL(MODULE,'MFG')MODULE,'TTL'EQP_G, 'TTL'EQP_ID,"TYPE",FCST_TIME,SUM(VALUE)VALUE FROM( SELECT EQP_G,MODULE,EQP_ID,'ACT' TYPE ,ACT_RETURN_TIME FCST_TIME ,1 VALUE FROM( SELECT EQP_G,MODULE,EQP_ID,'ACT' TYPE , CASE WHEN ACT_RETURN_TIME <= TO_DATE('2026-04-15 20:30','YYYY-MM-DD HH24:MI') THEN TO_DATE('2026-04-15 20:30','YYYY-MM-DD HH24:MI') WHEN TO_NUMBER(TO_CHAR(ACT_RETURN_TIME,'MI'))>30 THEN TRUNC(ACT_RETURN_TIME,'HH24')+1.5/24 ELSE TRUNC(ACT_RETURN_TIME,'HH24')+0.5/24 END ACT_RETURN_TIME ,CASE WHEN TO_NUMBER(TO_CHAR(FCST_RETURN_TIME,'MI'))>30 THEN TRUNC(FCST_RETURN_TIME,'HH24')+1.5/24 ELSE TRUNC(FCST_RETURN_TIME,'HH24')+0.5/24 END FCST_TIME FROM A1MFG.EQP_RECOVER_MONITOR_UPLOAD A LEFT JOIN CUR_TIME_INFO B ON 1=1 WHERE A.ACT_RETURN_TIME IS NOT NULL AND A.ACT_RETURN_TIME < B.CUR_TIME
AND A.PRIORITY = #{pri,jdbcType=VARCHAR}
))GROUP BY ROLLUP(MODULE),"TYPE",FCST_TIME )) SELECT MODULE,EQP_G,EQP_ID,"TYPE",TO_CHAR(FCST_TIME,'YYYY-MM-DD HH24:MI')FCST_TIME,VALUE FROM PLAN_INFO A UNION ALL SELECT MODULE,EQP_G,EQP_ID,"TYPE",TO_CHAR(FCST_TIME,'YYYY-MM-DD HH24:MI')FCST_TIME,VALUE FROM ACT_INFO A UNION ALL SELECT MODULE,'TTL' EQP_G,'TTL'EQP_ID,'Gap'TYPE,SHIFT_DATE_LINE ,CASE WHEN DATE_TIME<= CUR_TIME THEN ACT_SUM-PLAN_SUM END VALUE FROM( SELECT A.DATE_TIME,A.SHIFT_DATE_LINE,A.MODULE,A.CUR_TIME, NVL(NVL(B.VALUE_SUM,LAG(B.VALUE_SUM IGNORE NULLS)OVER(PARTITION BY A.MODULE ORDER BY A.DATE_TIME)),0)ACT_SUM ,NVL(NVL(C.VALUE_SUM,LAG(C.VALUE_SUM IGNORE NULLS)OVER(PARTITION BY A.MODULE ORDER BY A.DATE_TIME)),0)PLAN_SUM FROM TIME_FLOW_INFO A LEFT JOIN ACT_INFO B ON A.DATE_TIME = B.FCST_TIME AND A.MODULE = B.MODULE LEFT JOIN PLAN_INFO C ON A.DATE_TIME = C.FCST_TIME AND A.MODULE = C.MODULE )

WITH CUR_TIME_INFO AS( SELECT CASE WHEN TO_NUMBER(TO_CHAR(CUR_TIME,'MI'))>30 THEN TRUNC(CUR_TIME,'HH24')+0.5/24 ELSE TRUNC(CUR_TIME,'HH24')- 0.5/24 END CUR_TIME FROM( SELECT DECODE(#{curDate,jdbcType=VARCHAR},NULL,SYSDATE,TO_DATE(#{curDate,jdbcType=VARCHAR},'YYYY-MM-DD HH24:MI')) CUR_TIME FROM DUAL )), TIME_FLOW_INFO AS( SELECT * FROM( SELECT SHIFT_DATE_LINE,DATE_TIME,B.CUR_TIME FROM ( SELECT TO_CHAR(TO_DATE('2026-04-15 20:30','YYYY-MM-DD HH24:MI')+ROWNUM/24-1/24 ,'YYYY-MM-DD HH24:MI')SHIFT_DATE_LINE ,TO_DATE('2026-04-15 20:30','YYYY-MM-DD HH24:MI')+ROWNUM/24-1/24 DATE_TIME FROM DUAL CONNECT BY ROWNUM <= 109 )A LEFT JOIN CUR_TIME_INFO B ON A.DATE_TIME <= B.CUR_TIME )C LEFT JOIN ( SELECT DISTINCT EQP_G,MODULE FROM A1MFG.EQP_RECOVER_MONITOR_UPLOAD D )D ON 1=1 ) ,PLAN_INFO AS( SELECT MODULE,EQP_G,EQP_ID,"TYPE",FCST_TIME,VALUE,SUM(VALUE)OVER(PARTITION BY MODULE,EQP_G,EQP_ID,"TYPE" ORDER BY FCST_TIME )VALUE_SUM FROM( SELECT MODULE,EQP_G, 'TTL'EQP_ID,"TYPE",FCST_TIME,SUM(VALUE)VALUE FROM( SELECT EQP_G,MODULE,EQP_ID,'Plan' TYPE ,CASE WHEN FCST_RETURN_TIME <= TO_DATE('2026-04-15 20:30','YYYY-MM-DD HH24:MI') THEN TO_DATE('2026-04-15 20:30','YYYY-MM-DD HH24:MI') WHEN TO_NUMBER(TO_CHAR(FCST_RETURN_TIME,'MI'))>30 THEN TRUNC(FCST_RETURN_TIME,'HH24')+1.5/24 ELSE TRUNC(FCST_RETURN_TIME,'HH24')+0.5/24 END FCST_TIME ,1 VALUE FROM A1MFG.EQP_RECOVER_MONITOR_UPLOAD A
WHERE A.PRIORITY = #{pri,jdbcType=VARCHAR}
)GROUP BY MODULE,EQP_G,"TYPE",FCST_TIME )) ,ACT_INFO AS( SELECT MODULE,EQP_G,EQP_ID,"TYPE",FCST_TIME,VALUE,SUM(VALUE)OVER(PARTITION BY MODULE,EQP_G,EQP_ID,"TYPE" ORDER BY FCST_TIME )VALUE_SUM FROM( SELECT MODULE,EQP_G, 'TTL'EQP_ID,"TYPE",FCST_TIME,SUM(VALUE)VALUE FROM( SELECT EQP_G,MODULE,EQP_ID,'ACT' TYPE ,ACT_RETURN_TIME FCST_TIME ,1 VALUE FROM( SELECT EQP_G,MODULE,EQP_ID,'ACT' TYPE , CASE WHEN ACT_RETURN_TIME <= TO_DATE('2026-04-15 20:30','YYYY-MM-DD HH24:MI') THEN TO_DATE('2026-04-15 20:30','YYYY-MM-DD HH24:MI') WHEN TO_NUMBER(TO_CHAR(ACT_RETURN_TIME,'MI'))>30 THEN TRUNC(ACT_RETURN_TIME,'HH24')+1.5/24 ELSE TRUNC(ACT_RETURN_TIME,'HH24')+0.5/24 END ACT_RETURN_TIME ,CASE WHEN TO_NUMBER(TO_CHAR(FCST_RETURN_TIME,'MI'))>30 THEN TRUNC(FCST_RETURN_TIME,'HH24')+1.5/24 ELSE TRUNC(FCST_RETURN_TIME,'HH24')+0.5/24 END FCST_TIME FROM A1MFG.EQP_RECOVER_MONITOR_UPLOAD A LEFT JOIN CUR_TIME_INFO B ON 1=1 WHERE A.ACT_RETURN_TIME IS NOT NULL AND A.ACT_RETURN_TIME < B.CUR_TIME
AND A.PRIORITY = #{pri,jdbcType=VARCHAR}
))GROUP BY MODULE,EQP_G,"TYPE",FCST_TIME )) SELECT MODULE,EQP_G,EQP_ID,"TYPE",TO_CHAR(FCST_TIME,'YYYY-MM-DD HH24:MI')FCST_TIME,VALUE FROM PLAN_INFO A UNION ALL SELECT MODULE,EQP_G,EQP_ID,"TYPE",TO_CHAR(FCST_TIME,'YYYY-MM-DD HH24:MI')FCST_TIME,VALUE FROM ACT_INFO A UNION ALL SELECT MODULE,EQP_G,'TTL'EQP_ID,'Gap'TYPE,SHIFT_DATE_LINE ,CASE WHEN DATE_TIME<= CUR_TIME THEN ACT_SUM-PLAN_SUM END VALUE FROM( SELECT A.DATE_TIME,A.SHIFT_DATE_LINE,A.MODULE,A.EQP_G,A.CUR_TIME, NVL(NVL(B.VALUE_SUM,LAG(B.VALUE_SUM IGNORE NULLS)OVER(PARTITION BY A.MODULE,A.EQP_G ORDER BY A.DATE_TIME)),0)ACT_SUM ,NVL(NVL(C.VALUE_SUM,LAG(C.VALUE_SUM IGNORE NULLS)OVER(PARTITION BY A.MODULE,A.EQP_G ORDER BY A.DATE_TIME)),0)PLAN_SUM FROM TIME_FLOW_INFO A LEFT JOIN ACT_INFO B ON A.DATE_TIME = B.FCST_TIME AND A.EQP_G = B.EQP_G LEFT JOIN PLAN_INFO C ON A.DATE_TIME = C.FCST_TIME AND A.EQP_G = C.EQP_G )

WITH CUR_TIME_INFO AS( SELECT CASE WHEN TO_NUMBER(TO_CHAR(CUR_TIME,'MI'))>=30 THEN TRUNC(CUR_TIME,'HH24')+5/24 ELSE TRUNC(CUR_TIME,'HH24')- 0.5/24 END CUR_TIME FROM( SELECT DECODE(#{curDate,jdbcType=VARCHAR},NULL,SYSDATE,TO_DATE(#{curDate,jdbcType=VARCHAR},'YYYY-MM-DD HH24:MI')) CUR_TIME FROM DUAL )) SELECT MODULE,EQP_G, EQP_ID,"TYPE",FCST_TIME,SUM(VALUE)VALUE FROM( SELECT MODULE,EQP_G,EQP_ID,"TYPE",TO_CHAR(FCST_TIME,'YYYY-MM-DD HH24:MI')FCST_TIME,VALUE FROM( SELECT EQP_G,MODULE,EQP_ID,'Plan' TYPE ,CASE WHEN TO_NUMBER(TO_CHAR(FCST_RETURN_TIME,'MI'))>30 THEN TRUNC(FCST_RETURN_TIME,'HH24')+1.5/24 ELSE TRUNC(FCST_RETURN_TIME,'HH24')+0.5/24 END FCST_TIME ,1 VALUE FROM A1MFG.EQP_RECOVER_MONITOR_UPLOAD A WHERE A.EQP_G = #{eqpg,jdbcType=VARCHAR}
AND A.PRIORITY = #{pri,jdbcType=VARCHAR}
UNION ALL SELECT EQP_G,MODULE,EQP_ID,'ACT' TYPE ,ACT_RETURN_TIME FCST_TIME ,CASE WHEN FCST_TIME>=ACT_RETURN_TIME THEN 1 ELSE 0 END VALUE FROM( SELECT EQP_G,MODULE,EQP_ID,'ACT' TYPE , CASE WHEN TO_NUMBER(TO_CHAR(ACT_RETURN_TIME,'MI'))>30 THEN TRUNC(ACT_RETURN_TIME,'HH24')+1.5/24 ELSE TRUNC(ACT_RETURN_TIME,'HH24')+0.5/24 END ACT_RETURN_TIME ,CASE WHEN TO_NUMBER(TO_CHAR(FCST_RETURN_TIME,'MI'))>30 THEN TRUNC(FCST_RETURN_TIME,'HH24')+1.5/24 ELSE TRUNC(FCST_RETURN_TIME,'HH24')+0.5/24 END FCST_TIME FROM A1MFG.EQP_RECOVER_MONITOR_UPLOAD A LEFT JOIN CUR_TIME_INFO B ON 1=1 WHERE EQP_G = #{eqpg,jdbcType=VARCHAR} AND A.ACT_RETURN_TIME IS NOT NULL AND A.ACT_RETURN_TIME < B.CUR_TIME
AND A.PRIORITY = #{pri,jdbcType=VARCHAR}
) )) GROUP BY MODULE,EQP_G,EQP_ID,"TYPE",FCST_TIME
